1	--! 
2	--! @author:    N. Selvarajah
3	--! @brief:     This module describes a debouncer.
4	--! @details:   Set DEBOUNCE_SYNC_BITS to the number of bits to shift the input signal to synchronize it with the clock.
5	--! @details:   10 ms is a good value for DEBOUNCE_SYNC_BITS.
6	--!
7	--! @license This project is released under the terms of the MIT License. See LICENSE for more details.
8	--!
9	
10	library ieee;
11	use ieee.std_logic_1164.all;
12	use ieee.numeric_std.all;
13	
14	use work.utils_pkg.all;
15	
16	entity debouncer is
17	    generic (
18	        DEBOUNCE_SYNC_BITS: natural range 0 to to_bits(natural'high) := 10;
19	        POLARITY: std_ulogic
20	    );
21	    port (
22	        clk_in: in std_ulogic;
23	        input: in std_ulogic;
24	        output: out std_ulogic
25	    );
26	end entity;
27	
28	architecture behavioural of debouncer is
29	    signal debounce_counter: natural range 0 to 2**DEBOUNCE_SYNC_BITS - 1;
30	    signal input_sync: std_ulogic := not POLARITY;
31	    signal input_sync_d: std_ulogic := not POLARITY;
32	begin
33	    process (clk_in)
34	    begin
35	        if rising_edge(clk_in) then
36	            input_sync_d <= input;
37	            if input /= input_sync_d then
38	                debounce_counter <= 0;
39	            elsif debounce_counter < debounce_counter'subtype'high then
40	                debounce_counter <= debounce_counter + 1;
41	            else
42	                input_sync <= input;
43	                debounce_counter <= 0;
44	            end if;
45	        end if;
46	    end process;
